Generalize to N threads. <p>See problem 2. Use <code>owner = (next-1) % N</code>, and preferably one <code>Condition</code> per thread, so you wake exactly the next one.</p> Which version would you ship? <p>The semaphore version is simpler and has no shared counter. In real code you'd rarely need either. Ordering usually comes from a single thread or a queue.</p> Does <code>notify()</code> work here? <p>With exactly two threads, yes, because the only waiter is always the one whose turn it is. With more threads it can wake the wrong one, which then waits again, and you lose the wake-up.</p> Would virtual threads change anything? <p>Not the logic. On JDK 21–23, <code>wait()</code> inside <code>synchronized</code> pins the virtual thread's carrier. That's harmless for two threads, but it matters at scale (see problem 8).</p> Full source: OddEvenPrinter.java <pre><code>import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Semaphore;

/**
 * Two threads print 1..N alternately: "odd" prints odd numbers, "even" prints even numbers.
 * Run: java OddEvenPrinter.java
 */
public class OddEvenPrinter {

    /** Approach 1: one monitor + wait/notifyAll. A shared counter decides whose turn it is. */
    static final class MonitorPrinter {
        private final int max;
        private int next = 1;                                   // guarded by "this"

        MonitorPrinter(int max) { this.max = max; }

        void print(boolean odd, List&lt;String&gt; out) throws InterruptedException {
            synchronized (this) {
                while (true) {
                    while (next &lt;= max &amp;&amp; isOdd(next) != odd) {
                        wait();                                 // not my turn: release monitor and sleep
                    }
                    if (next &gt; max) {                           // finished: wake the other thread so it can exit too
                        notifyAll();
                        return;
                    }
                    out.add(Thread.currentThread().getName() + ":" + next);
                    next++;                                     // hand the turn over...
                    notifyAll();                                // ...and wake the other thread
                }
            }
        }

        private static boolean isOdd(int n) { return n % 2 == 1; }
    }

    /** Approach 2: two semaphores used as a baton. Exactly one of them has a permit at any time. */
    static final class SemaphorePrinter {
        private final Semaphore oddTurn = new Semaphore(1);    // odd goes first
        private final Semaphore evenTurn = new Semaphore(0);

        void odd(int max, List&lt;String&gt; out) throws InterruptedException {
            for (int i = 1; i &lt;= max; i += 2) {
                oddTurn.acquire();                             // wait for the baton
                out.add("odd:" + i);
                evenTurn.release();                            // pass the baton
            }
        }

        void even(int max, List&lt;String&gt; out) throws InterruptedException {
            for (int i = 2; i &lt;= max; i += 2) {
                evenTurn.acquire();
                out.add("even:" + i);
                oddTurn.release();
            }
        }
    }

    public static void main(String[] args) throws Exception {
        int max = 10;

        List&lt;String&gt; out1 = new ArrayList&lt;&gt;();                 // only touched while holding the monitor
        var p = new MonitorPrinter(max);
        Thread odd = Thread.ofPlatform().name("odd").start(() -&gt; run(() -&gt; p.print(true, out1)));
        Thread even = Thread.ofPlatform().name("even").start(() -&gt; run(() -&gt; p.print(false, out1)));
        odd.join();
        even.join();                                           // join() = happens-before: safe to read out1
        System.out.println("monitor  : " + out1);
        check(out1, max);

        List&lt;String&gt; out2 = new ArrayList&lt;&gt;();                 // release()-&gt;acquire() gives happens-before
        var s = new SemaphorePrinter();
        Thread o = Thread.ofVirtual().start(() -&gt; run(() -&gt; s.odd(max, out2)));
        Thread e = Thread.ofVirtual().start(() -&gt; run(() -&gt; s.even(max, out2)));
        o.join();
        e.join();
        System.out.println("semaphore: " + out2);
        check(out2, max);
        System.out.println("PASS");
    }

    interface Body { void run() throws InterruptedException; }

    static void run(Body b) {
        try { b.run(); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    }

    static void check(List&lt;String&gt; out, int max) {
        if (out.size() != max) throw new AssertionError("size " + out.size());
        for (int i = 0; i &lt; max; i++) {
            if (!out.get(i).endsWith(":" + (i + 1))) throw new AssertionError("wrong order at " + i + ": " + out);
        }
    }
}
</code></pre>

Can you do it with semaphores? <p>Yes. Use <code>Semaphore[] sem</code> with <code>sem[0]=1</code> and the rest at 0. Thread i loops: <code>sem[i].acquire(); print; sem[(i+1)%N].release();</code>. Each thread knows its own numbers (<code>id+1, id+1+N, …</code>). This is the N-thread version of the baton in problem 1.</p> Is this a good use of threads? <p>No. It's fully sequential, so one thread would be faster. It's a coordination exercise. In real systems, ordering comes from a single consumer or a partitioned queue.</p> What about virtual threads? <p>It works unchanged. <code>Condition.await()</code> parks the virtual thread without pinning (j.u.c locks never pin).</p> Full source: RoundRobinPrinter.java <pre><code>import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;

/**
 * N threads print 1..max in strict round-robin order: T0 prints 1, T1 prints 2, ... T(N-1) prints N, T0 prints N+1 ...
 * Run: java RoundRobinPrinter.java
 */
public class RoundRobinPrinter {

    private final ReentrantLock lock = new ReentrantLock();
    private final Condition[] turn;                  // one wait-set per thread: we wake exactly the next one
    private final int threads;
    private final int max;
    private int next = 1;                            // guarded by lock

    RoundRobinPrinter(int threads, int max) {
        this.threads = threads;
        this.max = max;
        this.turn = new Condition[threads];
        for (int i = 0; i &lt; threads; i++) turn[i] = lock.newCondition();
    }

    private int owner(int number) { return (number - 1) % threads; }

    void worker(int id, List&lt;String&gt; out) throws InterruptedException {
        lock.lock();
        try {
            while (true) {
                while (next &lt;= max &amp;&amp; owner(next) != id) {
                    turn[id].await();                // releases the lock while waiting
                }
                if (next &gt; max) {                    // done: wake everybody so they observe next &gt; max and exit
                    for (Condition c : turn) c.signalAll();
                    return;
                }
                out.add("T" + id + ":" + next);
                next++;
                turn[owner(next)].signal();          // wake ONLY the thread whose turn it is now
            }
        } finally {
            lock.unlock();
        }
    }

    public static void main(String[] args) throws Exception {
        int n = 4, max = 20;
        var printer = new RoundRobinPrinter(n, max);
        List&lt;String&gt; out = new ArrayList&lt;&gt;();        // guarded by printer.lock
        List&lt;Thread&gt; ts = new ArrayList&lt;&gt;();
        for (int id = n - 1; id &gt;= 0; id--) {        // start in reverse order on purpose
            int myId = id;
            ts.add(Thread.ofVirtual().name("T" + id).start(() -&gt; {
                try { printer.worker(myId, out); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
            }));
        }
        for (Thread t : ts) t.join();
        System.out.println(out);
        for (int i = 0; i &lt; max; i++) {
            String expected = "T" + (i % n) + ":" + (i + 1);
            if (!out.get(i).equals(expected)) throw new AssertionError("expected " + expected + " got " + out.get(i));
        }
        System.out.println("PASS");
    }
}
</code></pre>

How would you avoid waking all four threads each time? <p>Use one <code>Condition</code> per role (as in problem 2). After printing <code>current</code>, compute which role owns <code>current+1</code> and signal only that condition.</p> Solve it with semaphores. <p>Give each role its own semaphore, with <code>number</code> starting at 1. A dispatcher loop (or the number thread) decides who owns the next number and releases that semaphore. Each printer does <code>acquire → print → release(dispatcher)</code>.</p> Full source: FizzBuzzMultithreaded.java <pre><code>import java.util.ArrayList;
import java.util.List;
import java.util.function.IntFunction;
import java.util.function.IntPredicate;

/**
 * LeetCode 1195. Four threads: one prints "Fizz" (div by 3 only), one "Buzz" (div by 5 only), one "FizzBuzz"
 * (div by 15), one prints the number. Together they must produce the normal FizzBuzz sequence.
 * Run: java FizzBuzzMultithreaded.java
 */
public class FizzBuzzMultithreaded {

    private final int n;
    private int current = 1;                                  // guarded by this
    private final List&lt;String&gt; out;

    FizzBuzzMultithreaded(int n, List&lt;String&gt; out) { this.n = n; this.out = out; }

    /** Generic "my turn?" loop shared by all four threads. Only the predicate and the printer differ. */
    private synchronized void loop(IntPredicate mine, IntFunction&lt;String&gt; render) throws InterruptedException {
        while (true) {
            while (current &lt;= n &amp;&amp; !mine.test(current)) wait();
            if (current &gt; n) { notifyAll(); return; }
            out.add(render.apply(current));
            current++;
            notifyAll();                                      // 4 threads, 4 conditions: notify() could wake the wrong one
        }
    }

    void fizz()     throws InterruptedException { loop(i -&gt; i % 3 == 0 &amp;&amp; i % 5 != 0, i -&gt; "Fizz"); }
    void buzz()     throws InterruptedException { loop(i -&gt; i % 5 == 0 &amp;&amp; i % 3 != 0, i -&gt; "Buzz"); }
    void fizzbuzz() throws InterruptedException { loop(i -&gt; i % 15 == 0,              i -&gt; "FizzBuzz"); }
    void number()   throws InterruptedException { loop(i -&gt; i % 3 != 0 &amp;&amp; i % 5 != 0, Integer::toString); }

    interface Body { void run() throws InterruptedException; }

    public static void main(String[] args) throws Exception {
        int n = 30;
        List&lt;String&gt; out = new ArrayList&lt;&gt;();
        var fb = new FizzBuzzMultithreaded(n, out);
        List&lt;Body&gt; bodies = List.of(fb::fizz, fb::buzz, fb::fizzbuzz, fb::number);
        List&lt;Thread&gt; threads = new ArrayList&lt;&gt;();
        for (Body b : bodies) {
            threads.add(Thread.ofVirtual().start(() -&gt; {
                try { b.run(); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
            }));
        }
        for (Thread t : threads) t.join();
        System.out.println(String.join(" ", out));
        for (int i = 1; i &lt;= n; i++) {
            String exp = i % 15 == 0 ? "FizzBuzz" : i % 3 == 0 ? "Fizz" : i % 5 == 0 ? "Buzz" : Integer.toString(i);
            if (!out.get(i - 1).equals(exp)) throw new AssertionError(i + ": " + out.get(i - 1));
        }
        System.out.println("PASS");
    }
}
</code></pre>

What if <code>first()</code> may be called many times, with alternating first/second? <p>Then it's turn-taking, not a one-shot dependency. Use semaphores (as in problem 1), because a latch can't be reset.</p> Latch vs <code>join()</code>? <p><code>t1.join()</code> requires a reference to the thread. A latch decouples who signals from who waits, and works with pools and virtual threads.</p> Full source: PrintInOrder.java <pre><code>import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.CountDownLatch;

/**
 * LeetCode 1114. Three threads call first(), second(), third() in ANY order; the output must be first, second, third.
 * Run: java PrintInOrder.java
 */
public class PrintInOrder {

    static final class Foo {
        private final CountDownLatch firstDone = new CountDownLatch(1);
        private final CountDownLatch secondDone = new CountDownLatch(1);

        void first(Runnable printFirst) {
            printFirst.run();
            firstDone.countDown();                     // opens gate 1 (and publishes everything before it)
        }

        void second(Runnable printSecond) throws InterruptedException {
            firstDone.await();                         // blocks until gate 1 is open
            printSecond.run();
            secondDone.countDown();
        }

        void third(Runnable printThird) throws InterruptedException {
            secondDone.await();
            printThird.run();
        }
    }

    /** Same ordering expressed as a dependency chain of CompletableFutures. */
    static final class FooCf {
        private final CompletableFuture&lt;Void&gt; firstDone = new CompletableFuture&lt;&gt;();
        private final CompletableFuture&lt;Void&gt; secondDone = new CompletableFuture&lt;&gt;();

        void first(Runnable r)  { r.run(); firstDone.complete(null); }
        void second(Runnable r) { firstDone.join(); r.run(); secondDone.complete(null); }
        void third(Runnable r)  { secondDone.join(); r.run(); }
    }

    public static void main(String[] args) throws Exception {
        for (int round = 0; round &lt; 200; round++) {             // repeat to shake out races
            List&lt;String&gt; out = new CopyOnWriteArrayList&lt;&gt;();
            var foo = new Foo();
            Thread t3 = Thread.ofVirtual().start(() -&gt; uncheck(() -&gt; foo.third(() -&gt; out.add("third"))));
            Thread t2 = Thread.ofVirtual().start(() -&gt; uncheck(() -&gt; foo.second(() -&gt; out.add("second"))));
            Thread t1 = Thread.ofVirtual().start(() -&gt; foo.first(() -&gt; out.add("first")));
            t1.join(); t2.join(); t3.join();
            if (!out.equals(List.of("first", "second", "third"))) throw new AssertionError(out);

            List&lt;String&gt; out2 = new CopyOnWriteArrayList&lt;&gt;();
            var cf = new FooCf();
            Thread a = Thread.ofVirtual().start(() -&gt; cf.third(() -&gt; out2.add("third")));
            Thread b = Thread.ofVirtual().start(() -&gt; cf.second(() -&gt; out2.add("second")));
            Thread c = Thread.ofVirtual().start(() -&gt; cf.first(() -&gt; out2.add("first")));
            a.join(); b.join(); c.join();
            if (!out2.equals(List.of("first", "second", "third"))) throw new AssertionError(out2);
        }
        System.out.println("200 rounds, threads started in reverse order, always: first second third");
        System.out.println("PASS");
    }

    interface Body { void run() throws InterruptedException; }

    static void uncheck(Body b) {
        try { b.run(); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    }
}
</code></pre>

What happens if a thread is interrupted while waiting at the barrier? <p>The barrier becomes broken: the others get <code>BrokenBarrierException</code>. In production, reset it (<code>barrier.reset()</code>) or fail the whole group. The <code>finally</code> still frees the seat.</p> Can you do it without CyclicBarrier? <p>Yes, with a lock, counters <code>h</code> and <code>o</code>, and a condition. When <code>h&gt;=2 &amp;&amp; o&gt;=1</code>, form a molecule by decrementing and signalling the members. It's longer, but it shows you understand what the barrier does internally (see problem 9).</p> Full source: H2OBuilder.java <pre><code>import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.CyclicBarrier;
import java.util.concurrent.Executors;
import java.util.concurrent.Semaphore;

/**
 * LeetCode 1117. Hydrogen and oxygen threads arrive randomly; they must leave in groups of exactly 2 H + 1 O.
 * Run: java H2OBuilder.java
 */
public class H2OBuilder {

    private final Semaphore hydrogenSlots = new Semaphore(2);   // at most 2 H in the current molecule
    private final Semaphore oxygenSlots = new Semaphore(1);     // at most 1 O in the current molecule
    private final CyclicBarrier molecule = new CyclicBarrier(3); // the 3 atoms wait for each other

    void hydrogen(Runnable releaseHydrogen) throws Exception {
        hydrogenSlots.acquire();          // 1. claim a seat in the molecule being formed
        try {
            molecule.await();             // 2. wait until 2 H + 1 O are seated
            releaseHydrogen.run();        // 3. "bond" (print)
        } finally {
            hydrogenSlots.release();      // 4. free the seat for the NEXT molecule
        }
    }

    void oxygen(Runnable releaseOxygen) throws Exception {
        oxygenSlots.acquire();
        try {
            molecule.await();
            releaseOxygen.run();
        } finally {
            oxygenSlots.release();
        }
    }

    public static void main(String[] args) throws Exception {
        int molecules = 500;
        List&lt;Character&gt; atoms = new ArrayList&lt;&gt;();
        for (int i = 0; i &lt; molecules; i++) { atoms.add('H'); atoms.add('H'); atoms.add('O'); }
        Collections.shuffle(atoms);

        List&lt;Character&gt; out = Collections.synchronizedList(new ArrayList&lt;&gt;());
        var h2o = new H2OBuilder();
        try (var ex = Executors.newVirtualThreadPerTaskExecutor()) {
            for (char a : atoms) {
                ex.submit(() -&gt; {
                    if (a == 'H') h2o.hydrogen(() -&gt; out.add('H'));
                    else h2o.oxygen(() -&gt; out.add('O'));
                    return null;
                });
            }
        }
        for (int i = 0; i &lt; out.size(); i += 3) {
            long h = out.subList(i, i + 3).stream().filter(c -&gt; c == 'H').count();
            if (h != 2) throw new AssertionError("group " + i / 3 + " = " + out.subList(i, i + 3));
        }
        System.out.println(molecules + " molecules, every consecutive group of 3 is 2xH + 1xO, e.g. "
                + out.subList(0, 9));
        System.out.println("PASS");
    }
}
</code></pre>

How would you get more throughput? <p>Use two locks, one for <code>put</code> (tail) and one for <code>take</code> (head), with an atomic count, like <code>LinkedBlockingQueue</code>. Producers and consumers then don't contend with each other.</p> How do you add <code>drainTo</code> / batch take? <p>Take the lock once, dequeue up to <code>max</code> items, then <code>notFull.signalAll()</code> (several producers can now proceed).</p> Why <code>lockInterruptibly</code> but <code>lock()</code> in <code>size()</code>? <p><code>size()</code> never waits for a condition, so it holds the lock only briefly, and there's nothing worth interrupting.</p> Full source: BoundedBlockingQueue.java <pre><code>import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.LongAdder;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;

/**
 * LeetCode 1188 / classic: implement a bounded blocking queue with put/take (+ timed offer) from scratch.
 * Run: java BoundedBlockingQueue.java
 */
public class BoundedBlockingQueue&lt;E&gt; {

    private final Object[] items;                 // circular buffer
    private int head;                             // next slot to take from
    private int tail;                             // next slot to put into
    private int count;                            // number of elements
    private final ReentrantLock lock = new ReentrantLock();
    private final Condition notFull = lock.newCondition();   // producers wait here
    private final Condition notEmpty = lock.newCondition();  // consumers wait here

    public BoundedBlockingQueue(int capacity) {
        if (capacity &lt;= 0) throw new IllegalArgumentException("capacity must be &gt; 0");
        items = new Object[capacity];
    }

    public void put(E e) throws InterruptedException {
        if (e == null) throw new NullPointerException();
        lock.lockInterruptibly();                 // a blocked producer can still be cancelled
        try {
            while (count == items.length) {
                notFull.await();                  // queue full → wait for a consumer
            }
            enqueue(e);
            notEmpty.signal();                    // exactly one consumer can now make progress
        } finally {
            lock.unlock();
        }
    }

    public E take() throws InterruptedException {
        lock.lockInterruptibly();
        try {
            while (count == 0) {
                notEmpty.await();                 // queue empty → wait for a producer
            }
            E e = dequeue();
            notFull.signal();                     // exactly one producer can now make progress
            return e;
        } finally {
            lock.unlock();
        }
    }

    /** Timed offer: gives up after the timeout. awaitNanos returns the time still left. */
    public boolean offer(E e, long timeout, TimeUnit unit) throws InterruptedException {
        long nanos = unit.toNanos(timeout);
        lock.lockInterruptibly();
        try {
            while (count == items.length) {
                if (nanos &lt;= 0) return false;
                nanos = notFull.awaitNanos(nanos);
            }
            enqueue(e);
            notEmpty.signal();
            return true;
        } finally {
            lock.unlock();
        }
    }

    private void enqueue(E e) {                   // caller holds lock
        items[tail] = e;
        tail = (tail + 1) % items.length;
        count++;
    }

    @SuppressWarnings("unchecked")
    private E dequeue() {                         // caller holds lock
        E e = (E) items[head];
        items[head] = null;                       // let GC reclaim it
        head = (head + 1) % items.length;
        count--;
        return e;
    }

    public int size() {
        lock.lock();
        try { return count; } finally { lock.unlock(); }
    }

    public static void main(String[] args) throws Exception {
        var q = new BoundedBlockingQueue&lt;Integer&gt;(8);              // tiny capacity → lots of blocking
        int producers = 20, perProducer = 5_000;
        LongAdder sum = new LongAdder();
        try (var ex = Executors.newVirtualThreadPerTaskExecutor()) {
            for (int p = 0; p &lt; producers; p++) {
                ex.submit(() -&gt; { for (int i = 1; i &lt;= perProducer; i++) q.put(i); return null; });
            }
            for (int c = 0; c &lt; 10; c++) {
                ex.submit(() -&gt; { for (int i = 0; i &lt; producers * perProducer / 10; i++) sum.add(q.take()); return null; });
            }
        }
        long expected = (long) producers * perProducer * (perProducer + 1) / 2;
        if (sum.sum() != expected || q.size() != 0) throw new AssertionError(sum.sum() + " vs " + expected);
        boolean accepted = new BoundedBlockingQueue&lt;Integer&gt;(1) {{ put(1); }}.offer(2, 50, TimeUnit.MILLISECONDS);
        if (accepted) throw new AssertionError("offer on a full queue must time out");
        System.out.printf("20 producers x 5000 items through capacity 8: sum=%d (expected %d), timed offer on full queue=%s%n",
                sum.sum(), expected, accepted);
        System.out.println("PASS");
    }
}
</code></pre>

How does ThreadPoolExecutor grow from core to max size? <p>It adds core threads first, then queues, and only starts extra threads up to <code>max</code> when the queue is full. Then it rejects. See Executors.</p> How would you add a CallerRuns policy? <p>When <code>offer</code> fails, run <code>task.run()</code> on the submitting thread. That naturally slows the producer down.</p> Why not just use virtual threads? <p>For IO-bound tasks you would: <code>Executors.newVirtualThreadPerTaskExecutor()</code> + a <code>Semaphore</code>. A fixed pool remains right for CPU-bound work, sized to the core count.</p> Full source: SimpleThreadPool.java <pre><code>import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.Callable;
import java.util.concurrent.Future;
import java.util.concurrent.FutureTask;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * Build a fixed-size thread pool: bounded queue, Future results, rejection, graceful shutdown.
 * Run: java SimpleThreadPool.java
 */
public class SimpleThreadPool implements AutoCloseable {

    private final BlockingQueue&lt;Runnable&gt; queue;
    private final List&lt;Thread&gt; workers = new ArrayList&lt;&gt;();
    private final Object stateLock = new Object();    // makes "check shutdown + enqueue" atomic
    private volatile boolean shutdown;

    public SimpleThreadPool(int threads, int queueCapacity) {
        queue = new ArrayBlockingQueue&lt;&gt;(queueCapacity);
        for (int i = 0; i &lt; threads; i++) {
            workers.add(Thread.ofPlatform().name("pool-worker-", i).start(this::workerLoop));
        }
    }

    private void workerLoop() {
        while (true) {
            Runnable task;
            try {
                task = queue.poll(50, TimeUnit.MILLISECONDS);
            } catch (InterruptedException e) {
                return;                                // shutdownNow(): stop immediately
            }
            if (task == null) {
                if (shutdown &amp;&amp; queue.isEmpty()) return;  // drained and no more submissions → exit
                continue;
            }
            try {
                task.run();                            // FutureTask captures exceptions into the Future
            } catch (Throwable t) {
                // a bare Runnable threw: keep the worker alive (a real pool would log this)
            }
        }
    }

    public &lt;T&gt; Future&lt;T&gt; submit(Callable&lt;T&gt; callable) {
        FutureTask&lt;T&gt; task = new FutureTask&lt;&gt;(callable);
        synchronized (stateLock) {                     // see "the shutdown race" in the docs
            if (shutdown) throw new RejectedExecutionException("pool is shut down");
            if (!queue.offer(task)) throw new RejectedExecutionException("queue full");  // AbortPolicy
        }
        return task;
    }

    public void shutdown() {
        synchronized (stateLock) { shutdown = true; }  // after this no task can be enqueued
    }

    public List&lt;Runnable&gt; shutdownNow() {
        shutdown();
        List&lt;Runnable&gt; pending = new ArrayList&lt;&gt;();
        queue.drainTo(pending);
        workers.forEach(Thread::interrupt);
        return pending;
    }

    public boolean awaitTermination(long timeout, TimeUnit unit) throws InterruptedException {
        long deadline = System.nanoTime() + unit.toNanos(timeout);
        for (Thread w : workers) {
            long left = deadline - System.nanoTime();
            if (left &lt;= 0 || !w.join(java.time.Duration.ofNanos(left))) return false;
        }
        return true;
    }

    @Override
    public void close() throws InterruptedException {
        shutdown();
        if (!awaitTermination(30, TimeUnit.SECONDS)) shutdownNow();
    }

    public static void main(String[] args) throws Exception {
        AtomicInteger ran = new AtomicInteger();
        List&lt;Future&lt;Integer&gt;&gt; results = new ArrayList&lt;&gt;();
        try (var pool = new SimpleThreadPool(4, 1_000)) {
            for (int i = 0; i &lt; 500; i++) {
                int n = i;
                results.add(pool.submit(() -&gt; { ran.incrementAndGet(); return n * n; }));
            }
            Future&lt;Integer&gt; failing = pool.submit(() -&gt; { throw new IllegalStateException("boom"); });
            try { failing.get(); throw new AssertionError("expected failure"); }
            catch (java.util.concurrent.ExecutionException e) { System.out.println("failure captured in Future: " + e.getCause()); }
        }
        long sum = 0;
        for (Future&lt;Integer&gt; f : results) sum += f.get();
        long expected = 0; for (int i = 0; i &lt; 500; i++) expected += (long) i * i;
        if (sum != expected || ran.get() != 500) throw new AssertionError(sum + " " + ran);

        var tiny = new SimpleThreadPool(1, 1);
        tiny.submit(() -&gt; { Thread.sleep(200); return 0; });
        Thread.sleep(20);                                   // worker picks the first task
        tiny.submit(() -&gt; 1);                               // fills the queue (capacity 1)
        boolean rejected = false;
        try { tiny.submit(() -&gt; 2); } catch (RejectedExecutionException e) { rejected = true; }
        tiny.close();
        boolean rejectedAfterShutdown = false;
        try { tiny.submit(() -&gt; 3); } catch (RejectedExecutionException e) { rejectedAfterShutdown = true; }
        System.out.printf("500 tasks ok (sum of squares=%d), queue-full rejection=%s, post-shutdown rejection=%s%n",
                sum, rejected, rejectedAfterShutdown);
        if (!rejected || !rejectedAfterShutdown) throw new AssertionError();
        System.out.println("PASS");
    }
}
