ProductPageService.java<pre><code>package com.playbook.vt.application;

import com.playbook.vt.client.CatalogClient;
import com.playbook.vt.client.InventoryClient;
import com.playbook.vt.client.PricingClient;
import com.playbook.vt.concurrency.FanOut;
import com.playbook.vt.concurrency.RequestContext;
import com.playbook.vt.config.ConcurrencyProperties;
import com.playbook.vt.domain.Price;
import com.playbook.vt.domain.ProductPage;
import com.playbook.vt.domain.Stock;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.List;

/**
 * Fan-out aggregator. Catalog is REQUIRED (failure fails the request and cancels siblings); price and stock are
 * OPTIONAL (failure or deadline degrades to a default). All three run concurrently on virtual threads and share one
 * deadline, so total latency is roughly max(catalog, pricing, inventory) instead of their sum.
 *
 * &lt;p&gt;Java 8 equivalent: three CompletableFuture.supplyAsync calls on a sized pool, thenCombine chains, orTimeout and
 * exceptionally handlers, and no sibling cancellation. See docs/production/fan-out-service.md.
 */
@Service
public class ProductPageService {

    private static final Logger log = LoggerFactory.getLogger(ProductPageService.class);

    private final CatalogClient catalog;
    private final PricingClient pricing;
    private final InventoryClient inventory;
    private final FanOut fanOut;
    private final ConcurrencyProperties props;

    public ProductPageService(CatalogClient catalog, PricingClient pricing, InventoryClient inventory,
                              FanOut fanOut, ConcurrencyProperties props) {
        this.catalog = catalog;
        this.pricing = pricing;
        this.inventory = inventory;
        this.fanOut = fanOut;
        this.props = props;
    }

    public ProductPage page(String productId) throws InterruptedException {
        try (var scope = fanOut.open(props.fanOutTimeout())) {
            var product = scope.fork(RequestContext.propagate(() -&gt; catalog.get(productId)));
            var price = scope.forkOptional(RequestContext.propagate(() -&gt; pricing.get(productId)),
                    ex -&gt; { log.warn("pricing degraded: {}", ex.toString()); return Price.unknown(productId); });
            var stock = scope.forkOptional(RequestContext.propagate(() -&gt; inventory.get(productId)),
                    ex -&gt; { log.warn("inventory degraded: {}", ex.toString()); return Stock.unknown(productId); });

            var p = product.get();          // required: throws and cancels siblings on failure
            var pr = price.get();
            var st = stock.get();

            List&lt;String&gt; degraded = new ArrayList&lt;&gt;();
            if (price.degraded()) degraded.add("price");
            if (stock.degraded()) degraded.add("stock");
            return new ProductPage(p, pr, st, List.copyOf(degraded), Thread.currentThread().toString());
        }
    }
}
</code></pre>

FanOut.java<pre><code>package com.playbook.vt.concurrency;

import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.ThreadFactory;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.function.Function;

/**
 * Structured fan-out on virtual threads WITHOUT preview APIs.
 *
 * &lt;p&gt;Gives the guarantees of {@code StructuredTaskScope}: every subtask finishes (or is cancelled) before
 * {@link Scope#close()} returns, a failure of a required subtask cancels its siblings, and the whole fan-out
 * shares one deadline. When structured concurrency becomes final, only this class needs to change.
 */
public final class FanOut {

    private final ThreadFactory threadFactory;

    public FanOut(String threadNamePrefix) {
        this.threadFactory = Thread.ofVirtual().name(threadNamePrefix, 0).factory();
    }

    public Scope open(Duration deadline) {
        return new Scope(Executors.newThreadPerTaskExecutor(threadFactory), System.nanoTime() + deadline.toNanos());
    }

    /** A lexical scope that owns its subtasks. Always use with try-with-resources. */
    public static final class Scope implements AutoCloseable {
        private final ExecutorService executor;
        private final long deadlineNanos;
        private final List&lt;Future&lt;?&gt;&gt; forked = new ArrayList&lt;&gt;();

        private Scope(ExecutorService executor, long deadlineNanos) {
            this.executor = executor;
            this.deadlineNanos = deadlineNanos;
        }

        /** A subtask whose failure fails the whole scope. */
        public &lt;T&gt; Required&lt;T&gt; fork(Callable&lt;T&gt; task) {
            Future&lt;T&gt; f = executor.submit(task);
            forked.add(f);
            return new Required&lt;&gt;(f, this);
        }

        /** A subtask that falls back to a default value on failure or deadline. */
        public &lt;T&gt; Optional&lt;T&gt; forkOptional(Callable&lt;T&gt; task, Function&lt;Throwable, T&gt; fallback) {
            Future&lt;T&gt; f = executor.submit(task);
            forked.add(f);
            return new Optional&lt;&gt;(f, fallback, this);
        }

        long remainingNanos() {
            return Math.max(0, deadlineNanos - System.nanoTime());
        }

        void cancelAll() {
            forked.forEach(f -&gt; f.cancel(true)); // interrupt: blocking IO in siblings aborts promptly
        }

        @Override
        public void close() {
            cancelAll();        // no-op for completed subtasks
            executor.close();   // waits for cancelled subtasks to actually finish: nothing outlives the scope
        }
    }

    public static final class Required&lt;T&gt; {
        private final Future&lt;T&gt; future;
        private final Scope scope;

        Required(Future&lt;T&gt; future, Scope scope) {
            this.future = future;
            this.scope = scope;
        }

        public T get() throws InterruptedException {
            try {
                return future.get(scope.remainingNanos(), TimeUnit.NANOSECONDS);
            } catch (TimeoutException e) {
                scope.cancelAll();
                throw new DeadlineExceededException("required subtask exceeded the fan-out deadline");
            } catch (ExecutionException e) {
                scope.cancelAll();
                if (e.getCause() instanceof RuntimeException re) throw re;
                throw new IllegalStateException("required subtask failed", e.getCause());
            } catch (InterruptedException e) {
                scope.cancelAll();
                throw e;
            }
        }
    }

    public static final class Optional&lt;T&gt; {
        private final Future&lt;T&gt; future;
        private final Function&lt;Throwable, T&gt; fallback;
        private final Scope scope;
        private volatile boolean degraded;

        Optional(Future&lt;T&gt; future, Function&lt;Throwable, T&gt; fallback, Scope scope) {
            this.future = future;
            this.fallback = fallback;
            this.scope = scope;
        }

        public T get() throws InterruptedException {
            try {
                return future.get(scope.remainingNanos(), TimeUnit.NANOSECONDS);
            } catch (TimeoutException e) {
                future.cancel(true);
                degraded = true;
                return fallback.apply(e);
            } catch (ExecutionException e) {
                degraded = true;
                return fallback.apply(e.getCause());
            }
        }

        public boolean degraded() {
            return degraded;
        }
    }
}
</code></pre>

ErrorHandling.java<pre><code>package com.playbook.vt.api;

import com.playbook.vt.concurrency.BulkheadFullException;
import com.playbook.vt.concurrency.DeadlineExceededException;
