PinningMonitor.java<pre><code>package com.playbook.vt.concurrency;

import io.micrometer.core.instrument.Counter;
import io.micrometer.core.instrument.MeterRegistry;
import jdk.jfr.consumer.RecordedFrame;
import jdk.jfr.consumer.RecordingStream;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.DisposableBean;
import org.springframework.beans.factory.InitializingBean;

import java.time.Duration;

/**
 * Streams the JFR {@code jdk.VirtualThreadPinned} event in-process and exports it as a metric.
 *
 * &lt;p&gt;On JDK 21-23 this catches blocking inside {@code synchronized}. On JDK 24+ (JEP 491) it should only fire for
 * native frames or class initialisers. Alert on {@code jvm.virtual_threads.pinned} &amp;gt; 0.
 */
public class PinningMonitor implements InitializingBean, DisposableBean {

    private static final Logger log = LoggerFactory.getLogger(PinningMonitor.class);

    private final Counter pinned;
    private final Duration threshold;
    private RecordingStream stream;

    public PinningMonitor(MeterRegistry registry, Duration threshold) {
        this.pinned = Counter.builder("jvm.virtual_threads.pinned")
                .description("Virtual threads that blocked while pinned to their carrier")
                .register(registry);
        this.threshold = threshold;
    }

    @Override
    public void afterPropertiesSet() {
        stream = new RecordingStream();
        stream.enable("jdk.VirtualThreadPinned").withThreshold(threshold).withStackTrace();
        stream.onEvent("jdk.VirtualThreadPinned", event -&gt; {
            pinned.increment();
            if (event.getStackTrace() != null) {
                String top = event.getStackTrace().getFrames().stream()
                        .filter(RecordedFrame::isJavaFrame)
                        .map(f -&gt; f.getMethod().getType().getName() + "." + f.getMethod().getName()
                                + ":" + f.getLineNumber())
                        .filter(s -&gt; !s.startsWith("java.") &amp;&amp; !s.startsWith("jdk."))
                        .findFirst().orElse("&lt;jdk&gt;");
                log.warn("Virtual thread pinned for {} ms at {}", event.getDuration().toMillis(), top);
            }
        });
        stream.startAsync();
    }

    @Override
    public void destroy() {
        if (stream != null) stream.close();
    }
}
</code></pre>

RequestContext.java<pre><code>package com.playbook.vt.concurrency;

import java.util.concurrent.Callable;

/**
 * Request-scoped context with an explicit, bounded lifetime.
 *
 * &lt;p&gt;This sample targets Java 21 without preview features, so it is backed by a ThreadLocal that is ALWAYS cleared in
 * {@code finally}. On Java 25 swap the body for {@code ScopedValue} (final, JEP 506); callers do not change:
 *
 * &lt;pre&gt;{@code
 * private static final ScopedValue&lt;String&gt; REQUEST_ID = ScopedValue.newInstance();
 * public static &lt;T&gt; T callWith(String id, Callable&lt;T&gt; c) throws Exception {
 *     return ScopedValue.where(REQUEST_ID, id).call(c::call);
 * }
 * public static String requestId() { return REQUEST_ID.orElse("none"); }
 * }&lt;/pre&gt;
 */
public final class RequestContext {

    private static final ThreadLocal&lt;String&gt; REQUEST_ID = new ThreadLocal&lt;&gt;();

    private RequestContext() {
    }

    public static &lt;T&gt; T callWith(String requestId, Callable&lt;T&gt; body) throws Exception {
        String previous = REQUEST_ID.get();
        REQUEST_ID.set(requestId);
        try {
            return body.call();
        } finally {
            if (previous == null) REQUEST_ID.remove();
            else REQUEST_ID.set(previous);
        }
    }

    public static String requestId() {
        String id = REQUEST_ID.get();
        return id == null ? "none" : id;
    }

    /** Wraps a task so the caller's context is re-bound inside a forked virtual thread. */
    public static &lt;T&gt; Callable&lt;T&gt; propagate(Callable&lt;T&gt; task) {
        String captured = REQUEST_ID.get();
        return captured == null ? task : () -&gt; callWith(captured, task);
    }
}
</code></pre> <p>The facade gives you three guarantees:</p> <ol> <li>A bounded lifetime: the value is cleared in <code>finally</code>, so it never leaks to the next request.</li> <li>Explicit propagation into forked VTs (<code>RequestContext.propagate</code>), because executors don't inherit context.</li> <li>A one-file migration to <code>ScopedValue</code> on Java 25.</li> </ol> <p>Its test proves both properties:</p> RequestContextTest.java<pre><code>package com.playbook.vt.concurrency;

import org.junit.jupiter.api.Test;

import java.util.concurrent.Executors;

import static org.assertj.core.api.Assertions.assertThat;

class RequestContextTest {

    @Test
    void contextIsBoundOnlyInsideScopeAndPropagatesToForkedThreads() throws Exception {
        assertThat(RequestContext.requestId()).isEqualTo("none");

        String inChild = RequestContext.callWith("req-42", () -&gt; {
            try (var ex = Executors.newVirtualThreadPerTaskExecutor()) {
                String plain = ex.submit(RequestContext::requestId).get();
                String propagated = ex.submit(RequestContext.propagate(RequestContext::requestId)).get();
                assertThat(plain).as("executors do not inherit context").isEqualTo("none");
                return propagated;
            }
        });

        assertThat(inChild).isEqualTo("req-42");
        assertThat(RequestContext.requestId()).as("cleared after scope").isEqualTo("none");
    }
}
</code></pre>

AdmissionControlFilter.java<pre><code>package com.playbook.vt.concurrency;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.web.filter.OncePerRequestFilter;

import java.io.IOException;
import java.util.concurrent.Semaphore;

/**
 * Caps requests in flight. With virtual threads Tomcat no longer runs out of threads, so without this a traffic spike
 * becomes an unbounded number of concurrent requests hammering every downstream. Excess load is shed with 503.
 */
public class AdmissionControlFilter extends OncePerRequestFilter {

    private final Semaphore inFlight;

    public AdmissionControlFilter(int maxInFlight) {
        this.inFlight = new Semaphore(maxInFlight);
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
        if (!inFlight.tryAcquire()) {
            response.setStatus(HttpStatus.SERVICE_UNAVAILABLE.value());
            response.setHeader("Retry-After", "1");
            response.setContentType(MediaType.APPLICATION_PROBLEM_JSON_VALUE);
            response.getWriter().write("""
                    {"type":"about:blank","title":"Service Unavailable","status":503,\
                    "detail":"Too many requests in flight"}""");
            return;
        }
        try {
            chain.doFilter(request, response);
        } finally {
            inFlight.release();
        }
    }

    @Override
    protected boolean shouldNotFilter(HttpServletRequest request) {
        return request.getRequestURI().startsWith("/actuator"); // never shed health checks
    }

    public int available() {
        return inFlight.availablePermits();
    }
}
</code></pre>

Bulkhead.java<pre><code>package com.playbook.vt.concurrency;

import io.micrometer.core.instrument.Counter;
import io.micrometer.core.instrument.Gauge;
import io.micrometer.core.instrument.MeterRegistry;
import io.micrometer.core.instrument.Timer;

import java.time.Duration;
import java.util.concurrent.Callable;
import java.util.concurrent.Semaphore;
import java.util.concurrent.TimeUnit;

/**
 * Semaphore bulkhead: THE way to limit concurrency once threads are virtual.
 *
 * &lt;p&gt;With platform threads the pool size implicitly capped calls to a dependency. With virtual threads there is no
 * such cap, so every dependency gets an explicit one. Callers that cannot get a permit within {@code maxWait} fail
 * fast instead of queuing forever, which isolates a slow dependency from the rest of the service.
 */
public final class Bulkhead {

    private final String name;
    private final int maxConcurrent;
    private final Semaphore permits;
    private final Duration maxWait;
    private final Counter rejected;
    private final Timer waitTimer;

    public Bulkhead(String name, int maxConcurrent, Duration maxWait, MeterRegistry registry) {
        if (maxConcurrent &lt;= 0) throw new IllegalArgumentException("maxConcurrent must be &gt; 0");
        this.name = name;
        this.maxConcurrent = maxConcurrent;
        this.permits = new Semaphore(maxConcurrent, true);
        this.maxWait = maxWait;
        this.rejected = Counter.builder("bulkhead.rejected").tag("name", name).register(registry);
        this.waitTimer = Timer.builder("bulkhead.wait").tag("name", name).register(registry);
        Gauge.builder("bulkhead.in_use", this, Bulkhead::inUse).tag("name", name).register(registry);
    }

    public &lt;T&gt; T call(Callable&lt;T&gt; task) throws Exception {
        long start = System.nanoTime();
        boolean acquired = permits.tryAcquire(maxWait.toNanos(), TimeUnit.NANOSECONDS); // parks: VT unmounts
        waitTimer.record(System.nanoTime() - start, TimeUnit.NANOSECONDS);
        if (!acquired) {
            rejected.increment();
            throw new BulkheadFullException(name);
        }
        try {
            return task.call();
        } finally {
            permits.release();
        }
    }

    public int inUse() {
        return maxConcurrent - permits.availablePermits();
    }

    public String name() {
        return name;
    }
}
