        pool.execute(() -&gt; handle(s));                       // client #201 waits in the queue
    }
}
</code></pre> <pre><code>try (ServerSocket server = new ServerSocket(9000);
     var ex = Executors.newVirtualThreadPerTaskExecutor()) {
    while (true) {
        Socket s = server.accept();
        ex.submit(() -&gt; handle(s));                          // 100k concurrent clients is fine
    }
}

static void handle(Socket s) {
    try (s; var in = new BufferedReader(new InputStreamReader(s.getInputStream()));
         var out = new PrintWriter(s.getOutputStream(), true)) {
        for (String line; (line = in.readLine()) != null; ) out.println(line);  // blocking read: VT unmounts
    } catch (IOException e) { /* client went away */ }
}
</code></pre> <p>The handler code is identical. Only the executor changed, and capacity went from 200 clients to around 100,000.</p>

