    private final ReentrantLock lock = new ReentrantLock();
    private volatile Token token;

    public Token get() {
        Token t = token;
        if (t != null &amp;&amp; !t.expired()) return t;    // fast path: no lock at all
        lock.lock();                                // j.u.c locks park → unmount
        try {
            if (token == null || token.expired()) token = authClient.fetchToken();
            return token;
        } finally {
            lock.unlock();
        }
    }
}
</code></pre> <pre><code>// The original synchronized version is fine. JEP 491 removes the pinning.
